styl:
.white-bg.b-new-text-18 {  background:#fff  }
.b-new-text-18 .label, .b-new-text-18 .plys-logo {  display:inline-block  }
.b-new-text-18 .plys-logo {  padding:5px 12px;border:.8px solid #d2d2d2;border-radius:9.6px;vertical-align:middle  }
@media screen and (max-width:600px) {
  .b-new-text-18 .plys-logo {  margin-bottom:10px!important  }
}
.b-new-text-18 .little-big-text {  font-family:Helvetica!important;font-weight:700;font-size:18px;line-height:25px;color:#413e43  }
.b-new-text-18 .image-block {  display:inline-block;width:100%  }
@media screen and (max-width:600px) {
  .b-new-text-18 .image-block {  text-align:center!important  }
}
.b-new-text-18 .disp-ib {  display:inline-block;vertical-align:middle  }
.b-new-text-18 .pt32 {  padding-top:32px  }
.b-new-text-18 .pt44, .b-new-text-18 .pt45 {  padding-top:44px  }
.br-full-16.b-new-text-18 {  border-radius:16px;-moz-border-radius:16px;-webkit-border-radius:16px  }
.bg-bord-full.b-new-text-18 {  border:1px solid #eae9e9  }
.b-new-text-18 .pb32 {  padding-bottom:32px  }
.b-new-text-18 .big-blue-text {  font-family:Helvetica!important;font-weight:700;font-size:56px;line-height:67px;color:#4575fe  }
@media screen and (max-width:600px) {
  .b-new-text-18 .big-blue-text {  font-size:36px!important;line-height:47px!important;text-align:center!important  }
}
